class Solution {
public:
    int balancedStringSplit(std::string s) {
        int bal = 0, ans = 0;
        for (char ch : s) {
            bal += (ch == 'R' ? 1 : -1);
            if (bal == 0) ans++;
        }
        return ans;
    }
};

class Solution {
    public int balancedStringSplit(String s) {
        int bal = 0, ans = 0;
        for (char ch : s.toCharArray()) {
            bal += (ch == 'R' ? 1 : -1);
            if (bal == 0) ans++;
        }
        return ans;
    }
}

var balancedStringSplit = function(s) {
    let bal = 0, ans = 0;
    for (const ch of s) {
        bal += (ch === 'R' ? 1 : -1);
        if (bal === 0) ans++;
    }
    return ans;
};
